#!/usr/bin/env python3
"""Writes the tiny laya parity fixture read by tests/laya_parity.rs.

A 2-layer ModernBERT encoder (hidden 32, 2 heads, local_attention 4, so
the sliding band's edge falls inside a 12-token sequence) wrapped in
laya's OWN `DecisionModel`, seeded, saved under laya's prefixes, and run
once. Everything the Rust side must reproduce is recorded: the ids and
marker positions, every layer's hidden state, the marker rows the scorer
reads, the head logits, the tempered probabilities, and the act vector.

The reference is laya's class, imported from a clone — not a second
implementation of it written here. A fixture generated by a re-derivation
of the thing under test proves only that two of my readings agree.

Run from this directory with a Python that has torch and a transformers
carrying ModernBERT, and with the laya clone on the path:

    LAYA=/path/to/laya-clone .../ref-venv/bin/python laya_tiny.py

The engine's tests read only `laya_tiny.safetensors`, `laya_tiny.json`
and `laya_tiny_config.json`; none of this runs in the gate.
"""
import json
import os
import sys

import numpy as np
import torch

LAYA = os.environ.get("LAYA")
if not LAYA:
    sys.exit("set LAYA to the laya clone (it holds the reference DecisionModel)")
sys.path.insert(0, LAYA)

from laya.common import QTYPES, DecisionModel  # noqa: E402
from transformers import ModernBertConfig, ModernBertModel  # noqa: E402

SEED = 20260922
HIDDEN = 32
LAYERS = 2
HEADS = 2
INTERMEDIATE = 24
VOCAB = 64
# HF states the whole width; the reader halves it once. 4 -> a radius of
# 2, so a 12-token sequence has keys inside and outside the band and an
# off-by-one in the mask cannot hide.
LOCAL_ATTENTION = 4
CLS, SEP, MASK, PAD = 1, 2, 3, 0


def main() -> None:
    torch.manual_seed(SEED)
    cfg = ModernBertConfig(
        vocab_size=VOCAB,
        hidden_size=HIDDEN,
        intermediate_size=INTERMEDIATE,
        num_hidden_layers=LAYERS,
        num_attention_heads=HEADS,
        local_attention=LOCAL_ATTENTION,
        # Layer 0 global, layer 1 sliding: both rotary bases turn in one
        # forward pass, which is the thing a single-base port gets wrong
        # while still producing plausible numbers.
        global_attn_every_n_layers=3,
        global_rope_theta=160000.0,
        local_rope_theta=10000.0,
        norm_eps=1e-5,
        norm_bias=False,
        attention_bias=False,
        mlp_bias=False,
        cls_token_id=CLS,
        sep_token_id=SEP,
        pad_token_id=PAD,
        max_position_embeddings=512,
        attn_implementation="eager",
    )
    encoder = ModernBertModel(cfg)
    model = DecisionModel(encoder, head_layers=1, n_act=2).eval()

    # Real weights, not the near-zero initialisation: a layer that does
    # nothing agrees with any port of it.
    #
    # The scales are chosen so the OUTPUTS discriminate, which is the
    # whole point of a parity fixture. Uniform noise through this stack
    # saturates the act head — softmax at 1.0 and 1e-17 agrees with any
    # implementation that gets the sign right — and leaves the scorer's
    # logits at O(0.01), where a 1e-4 bound is looser than it looks. So
    # the two readout heads are scaled down until their outputs sit in a
    # range where being wrong shows.
    def scale_of(name: str) -> float:
        if name.startswith("act_head."):
            return 0.02
        if name.startswith("scorer."):
            return 0.9
        return 0.3

    with torch.no_grad():
        for name, p in model.named_parameters():
            p.copy_(torch.randn_like(p) * scale_of(name))
        for name, buf in model.named_buffers():
            if name == "temperature":
                buf.copy_(torch.tensor([1.1, 1.2, 1.3]))

    # One batch of two questions over the same state, which is what a
    # request looks like: different marker counts, so the padding of
    # `marker_pos` and the -1e4 fill both appear.
    ids = torch.tensor([
        [CLS, 10, 11, 12, SEP, MASK, 20, 21, MASK, 30, SEP, 40, 41, 42, SEP],
        [CLS, 13, 14, SEP, MASK, 22, MASK, 31, MASK, 33, SEP, 43, 44, SEP, PAD],
    ], dtype=torch.long)
    attention = torch.tensor([
        [1] * 15,
        [1] * 14 + [0],
    ], dtype=torch.long)
    marker_pos = torch.tensor([[5, 8, 0], [4, 6, 8]], dtype=torch.long)
    marker_mask = torch.tensor([[True, True, False], [True, True, True]], dtype=torch.bool)
    qtype = torch.tensor([QTYPES["choice"], QTYPES["noul"]], dtype=torch.long)

    taps = {}
    hooks = []

    def tap(i):
        def hook(_m, _in, out):
            h = out[0] if isinstance(out, tuple) else out
            taps[f"layer{i}"] = h.detach().float().numpy()
        return hook

    for i, layer in enumerate(encoder.layers):
        hooks.append(layer.register_forward_hook(tap(i)))

    with torch.no_grad():
        embedded = encoder.embeddings(ids)
        logits, act_logits = model(ids, attention, marker_pos, marker_mask, qtype)
        encoded = encoder(input_ids=ids, attention_mask=attention).last_hidden_state
    for h in hooks:
        h.remove()

    # What the readout makes of those logits, at this checkpoint's own
    # per-type temperatures.
    temperature = model.temperature.detach().float().numpy()
    probs = []
    for r in range(ids.shape[0]):
        k = int(marker_mask[r].sum())
        z = logits[r, :k].numpy() / temperature[int(qtype[r])]
        e = np.exp(z - z.max())
        probs.append((e / e.sum()).tolist())
    act = torch.softmax(act_logits.float(), -1).numpy()

    # The marker rows the scorer reads: AFTER the head, which is where
    # laya gathers them.
    h = encoded + model.type_emb(qtype)[:, None, :]
    with torch.no_grad():
        pad = ~attention.bool()
        for layer in model.head.layers:
            h = layer(h, src_key_padding_mask=pad)
        idx = marker_pos.clamp(min=0)[:, :, None].expand(-1, -1, h.size(-1))
        marker_hidden = torch.gather(h, 1, idx).float().numpy()
        pooled = h[:, 0].float().numpy()

    here = os.path.dirname(os.path.abspath(__file__))
    from safetensors.torch import save_file
    state = {k: v.contiguous() for k, v in model.state_dict().items()}
    save_file(state, os.path.join(here, "laya_tiny.safetensors"))
    with open(os.path.join(here, "laya_tiny_config.json"), "w") as f:
        json.dump(json.loads(cfg.to_json_string()), f, indent=1, sort_keys=True)

    # A WordLevel tokenizer over this vocabulary. The encoder does not
    # need one, but every reader of a model directory does, and the seat
    # commit will tokenize against exactly this.
    vocab = {"[PAD]": PAD, "[CLS]": CLS, "[SEP]": SEP, "[MASK]": MASK, "[UNK]": 4}
    for i in range(5, VOCAB):
        vocab["t%d" % i] = i
    tok = {
        "version": "1.0", "truncation": None, "padding": None,
        "added_tokens": [
            {"id": i, "content": c, "single_word": False, "lstrip": c == "[MASK]",
             "rstrip": False, "normalized": False, "special": True}
            for c, i in [("[PAD]", PAD), ("[CLS]", CLS), ("[SEP]", SEP), ("[MASK]", MASK), ("[UNK]", 4)]
        ],
        "normalizer": None,
        "pre_tokenizer": {"type": "WhitespaceSplit"},
        "post_processor": None, "decoder": None,
        "model": {"type": "WordLevel", "vocab": vocab, "unk_token": "[UNK]"},
    }
    with open(os.path.join(here, "laya_tiny_tokenizer.json"), "w") as f:
        json.dump(tok, f)

    out = {
        "_source": "laya DecisionModel from its own source; transformers %s, torch %s, seed %d"
                   % (__import__("transformers").__version__, torch.__version__, SEED),
        "geometry": {"hidden": HIDDEN, "layers": LAYERS, "heads": HEADS,
                     "intermediate": INTERMEDIATE, "vocab": VOCAB,
                     "local_attention": LOCAL_ATTENTION, "head_layers": 1, "n_act": 2},
        "input_ids": ids.tolist(),
        "attention_mask": attention.tolist(),
        "marker_pos": marker_pos.tolist(),
        "marker_mask": marker_mask.tolist(),
        "qtype": qtype.tolist(),
        "temperature": temperature.tolist(),
        "embedded": embedded.detach().float().numpy().tolist(),
        "layer0": taps["layer0"].tolist(),
        "layer1": taps["layer1"].tolist(),
        "encoded": encoded.float().numpy().tolist(),
        "marker_hidden": marker_hidden.tolist(),
        "pooled": pooled.tolist(),
        "logits": logits.float().numpy().tolist(),
        "probs": probs,
        "act": act.tolist(),
        "tensor_names": sorted(state.keys()),
    }
    with open(os.path.join(here, "laya_tiny.json"), "w") as f:
        json.dump(out, f)
    print("wrote laya_tiny.{safetensors,json,_config.json}: %d tensors, %d layers taps"
          % (len(state), LAYERS))
    # The health of the targets, said out loud: a saturated head or a
    # flat scorer makes a parity bound meaningless.
    lg = logits.float().numpy()
    print("  scorer logits  min %.3f  max %.3f (masked slots at -1e4 excluded: %s)"
          % (lg[lg > -1e3].min(), lg.max(), (lg <= -1e3).sum()))
    print("  probs          %s" % [[round(x, 3) for x in row] for row in probs])
    print("  act            %s" % [[round(float(x), 4) for x in row] for row in act])
    print("  |encoded|      mean %.3f  max %.3f" % (abs(encoded.numpy()).mean(), abs(encoded.numpy()).max()))


if __name__ == "__main__":
    main()
